<script>
(function(){
var _cs = document.currentScript;
function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (txt !== undefined) e.textContent = txt;
  return e;
}
var FF = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
var labs = ["Premiers 53\u00a0891\u00a0$", "53\u00a0891\u00a0$ à 58\u00a0523\u00a0$", "58\u00a0523\u00a0$ à 94\u00a0907\u00a0$", "94\u00a0907\u00a0$ à 107\u00a0785\u00a0$", "107\u00a0785\u00a0$ à 111\u00a0814\u00a0$", "111\u00a0814\u00a0$ à 117\u00a0045\u00a0$", "117\u00a0045\u00a0$ à 150\u00a0000\u00a0$", "150\u00a0000\u00a0$ à 181\u00a0440\u00a0$", "181\u00a0440\u00a0$ à 220\u00a0000\u00a0$", "220\u00a0000\u00a0$ à 258\u00a0482\u00a0$", "Plus de 258\u00a0482\u00a0$"];
var vals = [9.53, 11.58, 14.83, 15.74, 16.95, 18.95, 21.7, 22.48, 24.13, 24.91, 26.76];
var n = vals.length;
var margin = {left:110, top:18};
var PW = 546, PH = 236, MT = margin.top;
var xmax = Math.ceil(Math.max.apply(null, vals) / 5) * 5;
function xv(v){ return margin.left + (v / xmax) * PW; }
var gap = 5;
var barH = Math.floor((PH - (n - 1) * gap) / n);
function ry(i){ return MT + i * (barH + gap); }
function money(x){ var s = String(x); return (s.length > 3 ? s.slice(0, s.length - 3) + "\u00a0" + s.slice(-3) : s) + "\u00a0$"; }
var t, i;
for (t = 0; t <= xmax; t += 5) {
  svg.appendChild(el("line", {x1: xv(t), x2: xv(t), y1: MT, y2: MT + PH, stroke: "#ececec", "stroke-width": 0.5}));
}
for (i = 0; i < n; i++) {
  svg.appendChild(el("rect", {x: margin.left, y: ry(i), width: xv(vals[i]) - margin.left, height: barH, fill: "#4a5568"}));
}
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
var topI = n - 1;
var pillText = vals[topI].toFixed(2).replace(".", ",") + "\u00a0%";
var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
var pillH = 16;
var tipX = xv(vals[topI]);
var pillX = tipX - pillW - 6;
if (pillX < margin.left) pillX = margin.left;
var pillY = ry(topI) + barH / 2 - pillH / 2;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(el("text", {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111", "font-family": FF}, pillText));
for (i = 0; i < n; i++) {
  svg.appendChild(el("text", {x: margin.left - 6, y: ry(i) + barH / 2 + 3, "text-anchor": "end", "font-size": 8, fill: "#444444", "font-family": FF}, labs[i]));
  if (i !== topI) {
    svg.appendChild(el("text", {x: xv(vals[i]) + 6, y: ry(i) + barH / 2 + 3, "text-anchor": "start", "font-size": 8, fill: "#444444", "font-family": FF}, vals[i].toFixed(2).replace(".", ",") + "\u00a0%"));
  }
}
for (t = 0; t <= xmax; t += 5) {
  svg.appendChild(el("text", {x: xv(t), y: MT + PH + 16, "text-anchor": (t === xmax ? "end" : "middle"), "font-size": 8, fill: "#999999", "font-family": FF}, t + "\u00a0%"));
}
var labW = Math.ceil(("00,00\u00a0%").length * 8 * 0.58);
var clearX = Math.max(xv(vals[0]), xv(vals[1]), xv(vals[2]));
var ax = clearX + 6 + labW + 18;
var lo = Math.round(vals[0] * 100), hi = Math.round(vals[topI] * 100);
var note = ["PERTE DE 10\u00a0000\u00a0$ ÉCONOMISE", money(lo) + " À " + vals[0].toFixed(2).replace(".", ",") + "\u00a0%", money(hi) + " À " + vals[topI].toFixed(2).replace(".", ",") + "\u00a0%"];
note.forEach(function(s, k){
  svg.appendChild(el("text", {x: ax, y: ry(0) + 9 + k * 10, "text-anchor": "start", "font-size": 8, "font-weight": (k === 0 ? 700 : 400), fill: "#444444", "font-family": FF}, s));
});
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: TaxTips.ca, taux marginaux combinés fédéral et ontarien de 2026, consulté le 5 octobre 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Les taux sont les taux marginaux combinés fédéral et ontarien sur les gains en capital, avec un taux d’inclusion de 50&nbsp;%, surtaxes ontariennes comprises. Les montants en dollars de l’annotation multiplient chaque taux par 10&nbsp;000&nbsp;$.</p>
<p>Les taux diffèrent selon les provinces et pour les sociétés, de sorte que le tableau ne vise que les particuliers en Ontario. L’écart montre néanmoins pourquoi deux clients détenant le même titre perdant peuvent faire face à des décisions différentes&nbsp;: l’avantage est la perte multipliée par le taux applicable aux gains qu’elle compense, et le client de la tranche inférieure peut n’avoir aucun gain à compenser.</p>
<h2>La fenêtre de 61 jours piège les comptes les plus souvent oubliés</h2>
<p>La règle des pertes apparentes refuse une perte lorsque le même bien ou un bien identique est acheté dans les 30 jours précédant ou suivant la vente et qu’il est encore détenu à la fin de cette période. Cela fait une fenêtre de 61 jours. L’achat n’a pas à provenir du même compte ni de la même personne. Un conjoint ou conjoint de fait, une société contrôlée par le contribuable ou son conjoint, ainsi que le REER et le CELI du contribuable sont tous des personnes ou comptes affiliés aux fins de la règle.</p>
<p>Le dernier cas est le plus coûteux. Une perte refusée par suite d’un rachat dans un compte imposable est ajoutée au prix de base des nouvelles actions et récupérée lors d’une vente ultérieure. Un rachat dans un REER ou un CELI est perdu définitivement, parce que ces comptes n’ont pas de prix de base rajusté pour la recevoir. Un régime de réinvestissement qui achète automatiquement des actions dans un compte enregistré pendant la fenêtre produit le même résultat sans que personne ne passe d’ordre.</p>
<p>Détenir un titre semblable mais non identique permet de conserver l’exposition au marché pendant que la fenêtre court. Les ventes prévues pour la dernière semaine de décembre laissent le moins de marge, puisque les 30 jours suivant une vente du 30 décembre s’étendent jusqu’en janvier et qu’un achat par un conjoint ou par un compte enregistré à tout moment de cette période est visé.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients qui ont réalisé des gains cette année ressentent la menace d’une facture d’impôt à venir et veulent savoir si quelque chose peut la réduire. Les clients qui détiennent des positions en perte hésitent à vendre, parce qu’une perte réalisée donne l’impression d’une erreur rendue officielle. Les clients dont le conjoint ou la société investit aussi se sentent mal à l’aise devant une règle dont ils ont entendu parler sans la comprendre. Au fond de tout cela, il y a le souhait d’une réponse simple à la question de ce qu’on peut faire avant la fin de l’année.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Je vous appelle au sujet de la planification fiscale de fin d’année, et la date à retenir est le mercredi 30 décembre. C’est le dernier jour où une vente dans un compte non enregistré compte pour la présente année d’imposition. Si vous avez réalisé des gains cette année, une perte réalisée d’ici là peut les compenser, et si vous n’avez aucun gain cette année, une perte peut être reportée sur trois ans en arrière ou indéfiniment en avant. Deux mises en garde. Premièrement, une perte ne compte que si elle est réalisée dans un compte imposable, donc rien de ce qui se trouve dans votre REER ou votre CELI ne se qualifie. Deuxièmement, si vous ou votre conjoint achetez le même placement dans les trente jours précédant ou suivant la vente, la perte est refusée, et si l’achat se fait dans un REER ou un CELI, la perte est perdue pour de bon. Cela inclut le réinvestissement automatique. Je voudrais donc dresser la liste des positions en baisse, des gains réalisés jusqu’ici et des achats prévus pendant la même période. Pouvons-nous prévoir trente minutes dans les deux prochaines semaines pour tout passer en revue&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> Les clients des tranches supérieures qui ont réalisé de gros gains cette année, parce que chaque dollar de perte compense des gains imposés au taux combiné maximal, soit 26,76&nbsp;% en Ontario. Les clients qui détiennent le même titre dans un compte imposable, un REER, un CELI et un compte de conjoint courent le plus grand risque de déclencher la règle des pertes apparentes.</p>
<p><strong>Incidence variable&nbsp;:</strong> Les clients sans gains cette année, qui peuvent tout de même reporter des pertes sur 2023 à 2025 au moyen du formulaire T1A, et les clients des tranches inférieures, pour qui la même perte met à l’abri moins d’impôt.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> Les clients qui ont payé de l’impôt sur de gros gains en 2023, 2024 ou 2025 et qui détiennent aujourd’hui des pertes latentes, puisqu’un report rétrospectif peut récupérer de l’impôt déjà payé.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dresser la liste des positions non enregistrées dont la valeur est inférieure au prix de base rajusté, avec la perte en dollars pour chacune.</div>
<div class="checklist-item">Totaliser les gains réalisés en 2026 à ce jour et noter les gains de 2023 à 2025 qu’un report rétrospectif pourrait atteindre.</div>
<div class="checklist-item">Vérifier chaque achat, réinvestissement automatique et cotisation préautorisée chez le client, son conjoint, sa société, son REER et son CELI en regard de la fenêtre de 61 jours.</div>
<div class="checklist-item">Fixer la date de transaction au plus tard au mercredi 30 décembre et noter la fermeture hâtive de la Bourse de Toronto à 13&nbsp;h HE le 24 décembre.</div>
<div class="checklist-item">Suspendre le réinvestissement automatique des positions touchées et consigner le titre de remplacement retenu pour maintenir l’exposition.</div>
<div class="checklist-item">Consigner l’hypothèse de tranche utilisée pour chaque client et la confirmer avec le comptable.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Planification fiscale de fin d’année&nbsp;: le 30 décembre est la date à retenir<br><br>
Bonjour [Nom du client],<br><br>
Merci pour l’appel. Voici un résumé de ce dont nous avons discuté.<br><br>
Une perte réalisée dans un compte non enregistré peut compenser des gains en capital en 2026, ou être reportée sur trois ans en arrière ou indéfiniment en avant. Le dernier jour où une vente compte pour la présente année d’imposition est le mercredi 30 décembre. Les pertes réalisées dans un REER ou un CELI ne peuvent être déduites.<br><br>
Une règle à surveiller&nbsp;: si vous, votre conjoint ou une société que vous contrôlez achetez le même placement dans les trente jours précédant ou suivant la vente, la perte est refusée. Si l’achat se fait dans un REER ou un CELI, la perte est perdue définitivement. Cela inclut le réinvestissement automatique, que nous suspendrons au besoin.<br><br>
Prochaine étape&nbsp;: je vous enverrai la liste des positions qui pourraient se qualifier, avec les gains réalisés jusqu’ici cette année. Veuillez m’informer de tout achat prévu au cours des deux prochains mois et passer le plan en revue avec votre comptable.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes avec comptes imposables&nbsp;:</strong> Investisseurs qui gèrent eux-mêmes leurs placements, détiennent des positions en perte et n’ont suivi ni la règle des pertes apparentes ni leurs gains réalisés.</p>
<p><strong>Personnes à revenu élevé ayant des gains en 2026&nbsp;:</strong> Professionnels et propriétaires qui ont vendu des actions appréciées, levé des options ou vendu un bien cette année et qui font face à une facture plus élevée que prévu.</p>
<p><strong>Couples qui investissent séparément&nbsp;:</strong> Conjoints qui achètent et vendent les mêmes titres dans des comptes différents, où un achat peut refuser la perte de l’autre.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Je vous appelle parce que le dernier jour pour réaliser une perte en capital en 2026 est le 30 décembre, et beaucoup d’investisseurs autonomes ignorent que racheter la même action dans un REER ou un CELI annule la perte pour de bon. Avez-vous quelques minutes&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>La fin d’année crée une fenêtre courte, dictée par une échéance, où une petite règle entraîne un coût élevé. La valeur d’une perte de 10&nbsp;000&nbsp;$ varie de 953&nbsp;$ à 2&nbsp;676&nbsp;$ en Ontario selon la tranche, et un seul rachat dans le mauvais compte fait disparaître l’avantage en entier.</p>
<p>Le prospect qui gère seul n’a personne pour vérifier les achats chez un conjoint, dans une société et dans des comptes enregistrés. Un conseiller passe en revue tout le ménage au regard de la fenêtre de 61 jours et des gains déjà réalisés, puis se coordonne avec le comptable.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. Avez-vous vendu des placements à profit cette année, dans un compte imposable&nbsp;?</p>
<p>2. Détenez-vous des positions dans un compte imposable qui valent actuellement moins que ce que vous avez payé&nbsp;?</p>
<p>3. Votre conjoint ou une société que vous possédez détient-il certains des mêmes placements&nbsp;?</p>
<p>4. Certains de vos comptes sont-ils configurés pour réinvestir les dividendes ou acheter automatiquement&nbsp;?</p>
<p>5. Avez-vous payé de l’impôt sur des gains de placement au cours des trois dernières années&nbsp;?</p>
<p>6. Qui examine vos ventes de placements avant la préparation de votre déclaration de revenus&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Le 30 décembre et une règle qui peut annuler une perte fiscale<br><br>
Bonjour [Nom du prospect],<br><br>
Le dernier jour pour réaliser une perte en capital en 2026 est le 30 décembre. Une règle que bien des investisseurs négligent peut annuler la perte si le même placement est racheté dans les trente jours, et l’annulation devient définitive si l’achat se fait dans un REER ou un CELI.<br><br>
J’aide mes clients à cartographier gains, pertes et achats dans tout le ménage avant la fin de l’année. Un appel de vingt minutes la semaine prochaine vous serait-il utile&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"30 déc.","label":"Dernière date de transaction 2026"},{"value":"26,76 %","label":"Taux maximal en Ontario"},{"value":"9,53 %","label":"Taux première tranche Ontario"},{"value":"61 jours","label":"Fenêtre de perte apparente"}]',
