  '[{"value":"102,25 $","label":"Clôture du Brent, 2 octobre"},{"value":"18,3 M","label":"Exportations du Golfe (barils/jour)"},{"value":"7","label":"Incidents de pétroliers, semaine dernière"},{"value":"5,7 G$ CA","label":"Acquisition Athabasca par Cenovus"}]',
